#!/usr/bin/env node
/**
 * Generates the derived theme files from `theme/tokens.ts`, the single source of truth:
 *
 *   theme/global.css            CSS variables for :root and .dark (web + NativeWind input)
 *   theme/tailwind-tokens.cjs   the Tailwind `theme.extend` object (CommonJS, no literals)
 *
 * Run with `npm run theme:css`; `predev` / `prestart` / `prebuild` run it automatically so
 * the generated files can never drift from the tokens.
 *
 * Node >= 22.18 strips the TypeScript types on import, so this script reads tokens.ts directly.
 */
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { hexToRgbChannels, kebab } from "../theme/color.ts";
import {
  borderWidths,
  durations,
  easings,
  fontFallbacks,
  fontSizes,
  fonts,
  layout,
  lineHeights,
  opacities,
  radii,
  scalarTokenGroups,
  shadows,
  sizes,
  themeColors,
  zIndex,
} from "../theme/tokens.ts";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const banner = "/* GENERATED by scripts/build-theme-css.mjs from theme/tokens.ts — do not edit. */";

const cssVarNames = {
  color: (key) => `--color-${kebab(key)}`,
  shadow: (key) => `--shadow-${kebab(key)}`,
  font: (key) => `--font-${kebab(key)}`,
  easing: (key) => `--easing-${kebab(key)}`,
  scalar: (prefix, key) => `--${prefix}-${kebab(key)}`,
};

function colorBlock(colors, indent = "  ") {
  return Object.entries(colors)
    .map(([key, hex]) => `${indent}${cssVarNames.color(key)}: ${hexToRgbChannels(hex)};`)
    .join("\n");
}

function staticBlock(indent = "  ") {
  const lines = [`${indent}/* typography */`];

  for (const [key, stack] of Object.entries(fontFallbacks)) {
    const family = fonts[key];
    const value = key === "mono" ? stack : `"${family}", ${stack}`;
    lines.push(`${indent}${cssVarNames.font(key)}: ${value};`);
  }

  // Easings are tuples rather than scalars, so they get their own pass.
  lines.push(`${indent}/* easing */`);
  for (const [key, points] of Object.entries(easings)) {
    lines.push(`${indent}${cssVarNames.easing(key)}: cubic-bezier(${points.join(", ")});`);
  }

  // Every scalar category comes from the one registry in theme/tokens.ts, which
  // theme/vars.ts also reads, so the web and native variable names cannot diverge.
  for (const group of scalarTokenGroups) {
    lines.push(`${indent}/* ${group.prefix} */`);
    for (const [key, value] of Object.entries(group.record)) {
      lines.push(`${indent}${cssVarNames.scalar(group.prefix, key)}: ${value}${group.unit};`);
    }
  }

  return lines.join("\n");
}

function shadowBlock(indent = "  ") {
  return Object.entries(shadows)
    .map(([key, value]) => `${indent}${cssVarNames.shadow(key)}: ${value};`)
    .join("\n");
}

const css = `${banner}
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
${colorBlock(themeColors.scroll, "    ")}

${staticBlock("    ")}

${shadowBlock("    ")}
  }

  /* Explicit opt-in: <html class="dark"> or the ThemeProvider. */
  .dark:root,
  .dark {
${colorBlock(themeColors.nightScroll, "    ")}
  }

  @media (prefers-color-scheme: dark) {
    :root:not(.light) {
${colorBlock(themeColors.nightScroll, "      ")}
    }
  }

  * {
    border-color: rgb(var(${cssVarNames.color("border")}) / 1);
  }

  body {
    background-color: rgb(var(${cssVarNames.color("background")}) / 1);
    color: rgb(var(${cssVarNames.color("foreground")}) / 1);
    font-family: var(${cssVarNames.font("body")});
  }

  /*
   * On web, @rn-primitives/dialog wraps DialogContent in an unstyled Radix
   * <div role="dialog">. A percentage max-height on the content then resolves
   * against that auto-height block and does nothing, so a tall dialog overflows
   * the viewport instead of scrolling. Making the wrapper a shrinkable flex item
   * of the overlay gives it a definite height for \`max-h-full\` to resolve against.
   */
  [role="dialog"] {
    display: flex;
    flex-direction: column;
    min-height: 0;
    max-height: 100%;
  }
}
`;

const colorEntries = Object.keys(themeColors.scroll).map(
  (key) => `    "${kebab(key)}": "rgb(var(${cssVarNames.color(key)}) / <alpha-value>)",`,
);

const px = (record) =>
  Object.entries(record)
    .map(([key, value]) => `    "${key}": "${value}px",`)
    .join("\n");

const fontFamilyEntries = Object.entries(fontFallbacks)
  .map(([key, stack]) => {
    const families = key === "mono" ? stack.split(", ") : [fonts[key], ...stack.split(", ")];
    return `    "${key}": ${JSON.stringify(families)},`;
  })
  .join("\n");

const fontSizeEntries = Object.entries(fontSizes)
  .map(([key, size]) => `    "${key}": ["${size}px", { lineHeight: "${lineHeights[key]}px" }],`)
  .join("\n");

const tailwind = `${banner}
/** @type {import("tailwindcss").Config["theme"]} */
module.exports = {
  colors: {
${colorEntries.join("\n")}
  },
  fontFamily: {
${fontFamilyEntries}
  },
  fontSize: {
${fontSizeEntries}
  },
  spacing: {
${px(sizes)}
  },
  screens: {
    // The one breakpoint, as CSS: layout that only depends on width uses \`wide:\`
    // classes so the server-rendered HTML is right before any JS measures the window.
    "wide": "${layout.wideBreakpoint}px",
  },
  maxWidth: {
${px(layout)}
  },
  minWidth: {
${px(layout)}
  },
  width: {
${px({ ...sizes, ...layout })}
  },
  borderRadius: {
${px(radii)}
  },
  borderWidth: {
${px(borderWidths)}
  },
  ringWidth: {
${px(borderWidths)}
  },
  outlineWidth: {
${px(borderWidths)}
  },
  boxShadow: {
${Object.entries(shadows)
  .map(([key, value]) => `    "${kebab(key)}": "${value}",`)
  .join("\n")}
  },
  opacity: {
${Object.entries(opacities)
  .map(([key, value]) => `    "${key}": "${value}",`)
  .join("\n")}
  },
  transitionDuration: {
${Object.entries(durations)
  .map(([key, value]) => `    "${key}": "${value}ms",`)
  .join("\n")}
  },
  transitionTimingFunction: {
${Object.keys(easings)
  .map((key) => `    "${kebab(key)}": "var(${cssVarNames.easing(key)})",`)
  .join("\n")}
  },
  zIndex: {
${Object.entries(zIndex)
  .map(([key, value]) => `    "${key}": "${value}",`)
  .join("\n")}
  },
};
`;

writeFileSync(resolve(root, "theme/global.css"), css, "utf8");
writeFileSync(resolve(root, "theme/tailwind-tokens.cjs"), tailwind, "utf8");

console.log("theme: wrote theme/global.css and theme/tailwind-tokens.cjs from theme/tokens.ts");
